   1	/**
   2	 * RAG (Retrieval-Augmented Generation) — Vector storage and embedding abstractions.
   3	 *
   4	 * Provides a VectorStore interface for similarity search and an EmbeddingAdapter
   5	 * interface for converting text into vector representations.  Concrete backends
   6	 * (local SQLite, remote API) implement these interfaces so that the RAG pipeline
   7	 * is backend-agnostic.
   8	 */
   9	
  10	// ── Vector Document Types ────────────────────────────────────────────────────
  11	
  12	/** A document stored in the vector store with its embedding. */
  13	export interface VectorDocument {
  14	  /** Unique document ID */
  15	  id: string;
  16	  /** Original text content */
  17	  content: string;
  18	  /** Pre-computed embedding vector */
  19	  embedding: number[];
  20	  /** Optional metadata (source file, tags, etc.) */
  21	  metadata?: Record<string, unknown>;
  22	  /** ISO timestamp of creation */
  23	  createdAt: string;
  24	  /** ISO timestamp of last update */
  25	  updatedAt: string;
  26	}
  27	
  28	/** Minimal input required to add a document (embedding is computed by the adapter). */
  29	export interface VectorDocumentInput {
  30	  /** Unique document ID (auto-generated if omitted) */
  31	  id?: string;
  32	  /** Text content to embed and store */
  33	  content: string;
  34	  /** Optional metadata */
  35	  metadata?: Record<string, unknown>;
  36	}
  37	
  38	// ── Query Types ──────────────────────────────────────────────────────────────
  39	
  40	/** Options for a similarity search query. */
  41	export interface VectorQuery {
  42	  /** The query text (will be embedded by the adapter) or a pre-computed vector */
  43	  text?: string;
  44	  /** Pre-computed query vector (mutually exclusive with text) */
  45	  embedding?: number[];
  46	  /** Maximum number of results to return */
  47	  topK?: number;
  48	  /** Minimum similarity threshold (0-1). Results below this are filtered out. */
  49	  minScore?: number;
  50	  /** Optional metadata filter (exact-match on specified keys) */
  51	  filter?: Record<string, unknown>;
  52	  /** Whether to include the embedding vectors in results (default: false) */
  53	  includeEmbeddings?: boolean;
  54	}
  55	
  56	/** A single search result with its similarity score. */
  57	export interface VectorSearchResult {
  58	  /** The matched document */
  59	  document: VectorDocument;
  60	  /** Cosine similarity score (0-1) */
  61	  score: number;
  62	}
  63	
  64	/** The full result set from a vector search. */
  65	export interface VectorQueryResult {
  66	  /** Matching documents, sorted by score descending */
  67	  results: VectorSearchResult[];
  68	  /** Total number of documents considered */
  69	  total: number;
  70	  /** Time taken for the search in milliseconds */
  71	  durationMs: number;
  72	}
  73	
  74	// ── Index Statistics ─────────────────────────────────────────────────────────
  75	
  76	/** Statistics about the vector store index. */
  77	export interface VectorIndexStats {
  78	  /** Total number of documents in the index */
  79	  documentCount: number;
  80	  /** Dimensionality of the embedding vectors */
  81	  dimensions: number;
  82	  /** Approximate memory usage in bytes */
  83	  memoryBytes?: number;
  84	}
  85	
  86	// ── VectorStore Interface ────────────────────────────────────────────────────
  87	
  88	/**
  89	 * Core vector store interface.  All backends (local SQLite, in-memory, remote)
  90	 * implement this interface for storing and searching vector embeddings.
  91	 */
  92	export interface VectorStore {
  93	  /** Unique name of this store (e.g., "local-sqlite", "in-memory") */
  94	  readonly name: string;
  95	
  96	  /** Initialize the store (create tables, load indices, etc.) */
  97	  initialize(): Promise<void>;
  98	
  99	  /** Close the store and release resources */
 100	  close(): Promise<void>;
 101	
 102	  /** Check if the store is healthy */
 103	  isHealthy(): boolean;
 104	
 105	  // ── Document Operations ──────────────────────────────────────────────────
 106	
 107	  /** Add or update a document with its pre-computed embedding */
 108	  upsert(doc: VectorDocument): Promise<void>;
 109	
 110	  /** Add or update multiple documents in a batch */
 111	  upsertMany(docs: VectorDocument[]): Promise<void>;
 112	
 113	  /** Retrieve a document by ID. Returns undefined if not found. */
 114	  get(id: string): Promise<VectorDocument | undefined>;
 115	
 116	  /** Retrieve multiple documents by IDs */
 117	  getMany(ids: string[]): Promise<VectorDocument[]>;
 118	
 119	  /** Delete a document by ID. Returns true if it existed. */
 120	  delete(id: string): Promise<boolean>;
 121	
 122	  /** Delete multiple documents by IDs */
 123	  deleteMany(ids: string[]): Promise<number>;
 124	
 125	  /** Check if a document exists */
 126	  has(id: string): Promise<boolean>;
 127	
 128	  /** List all document IDs */
 129	  listIds(): Promise<string[]>;
 130	
 131	  /** Get the total number of documents */
 132	  count(): Promise<number>;
 133	
 134	  /** Clear all documents from the store */
 135	  clear(): Promise<void>;
 136	
 137	  // ── Similarity Search ────────────────────────────────────────────────────
 138	
 139	  /** Search for documents similar to the query */
 140	  search(query: VectorQuery): Promise<VectorQueryResult>;
 141	
 142	  // ── Index Management ─────────────────────────────────────────────────────
 143	
 144	  /** Get statistics about the vector index */
 145	  getStats(): Promise<VectorIndexStats>;
 146	}
 147	
 148	// ── Embedding Adapter Interface ──────────────────────────────────────────────
 149	
 150	/**
 151	 * Unified interface for generating text embeddings.
 152	 * Supports both local (ONNX/GGML) and remote (OpenAI/Anthropic) backends.
 153	 */
 154	export interface EmbeddingAdapter {
 155	  /** Unique name of this adapter (e.g., "openai", "local-onnx") */
 156	  readonly name: string;
 157	
 158	  /** The dimensionality of vectors produced by this adapter */
 159	  readonly dimensions: number;
 160	
 161	  /** Initialize the adapter (load model, verify API key, etc.) */
 162	  initialize(): Promise<void>;
 163	
 164	  /** Close the adapter and release resources */
 165	  close(): Promise<void>;
 166	
 167	  /** Embed a single text string */
 168	  embed(text: string): Promise<number[]>;
 169	
 170	  /** Embed multiple text strings in a batch */
 171	  embedBatch(texts: string[]): Promise<number[][]>;
 172	}
 173	
 174	// ── RAG Pipeline Types ───────────────────────────────────────────────────────
 175	
 176	/** Options for the RAG retrieval pipeline. */
 177	export interface RetrievalOptions {
 178	  /** Number of documents to retrieve */
 179	  topK?: number;
 180	  /** Minimum similarity score (0-1) */
 181	  minScore?: number;
 182	  /** Metadata filter */
 183	  filter?: Record<string, unknown>;
 184	  /** Whether to re-rank results after initial retrieval */
 185	  rerank?: boolean;
 186	}
 187	
 188	/** A retrieved chunk ready for context injection. */
 189	export interface RetrievedChunk {
 190	  /** Document ID */
 191	  id: string;
 192	  /** Text content of the chunk */
 193	  content: string;
 194	  /** Similarity score */
 195	  score: number;
 196	  /** Source metadata */
 197	  metadata?: Record<string, unknown>;
 198	}
