   1	/**
   2	 * Document Loader — Read files from disk and prepare them for vector indexing.
   3	 *
   4	 * Supports: Markdown, JSON, TypeScript/JavaScript, and plain text files.
   5	 * Automatically chunks large documents and preserves metadata (file path, type).
   6	 *
   7	 * Provides both synchronous (`load` / `loadFile`) and asynchronous
   8	 * (`loadAsync` / `loadFileAsync`) variants.  Async methods use
   9	 * `node:fs/promises` and are recommended for large codebases to avoid
  10	 * blocking the event loop.
  11	 */
  12	
  13	import { readFileSync, readdirSync, statSync } from "node:fs";
  14	import { readdir, readFile, stat } from "node:fs/promises";
  15	import { extname, join, relative } from "node:path";
  16	import type { Dirent } from "node:fs";
  17	import type { VectorDocumentInput } from "./types.js";
  18	import { RAGError } from "./types.js";
  19	
  20	// ── Types ────────────────────────────────────────────────────────────────────
  21	
  22	export type SupportedFileType = "markdown" | "json" | "typescript" | "text";
  23	
  24	export interface DocumentLoaderOptions {
  25	  /** Root directory to scan */
  26	  rootDir: string;
  27	  /** File extensions to include (default: all supported) */
  28	  extensions?: string[];
  29	  /** Patterns to exclude (glob-like, matched against relative path) */
  30	  exclude?: string[];
  31	  /** Maximum file size in bytes (default: 1MB) */
  32	  maxFileSize?: number;
  33	  /** Chunk size in characters (default: 1500) */
  34	  chunkSize?: number;
  35	  /** Chunk overlap in characters (default: 200) */
  36	  chunkOverlap?: number;
  37	  /** Custom prefix for document IDs (default: relative file path) */
  38	  idPrefix?: string;
  39	  /**
  40	   * Optional content preprocessor.  Receives raw file content and file type;
  41	   * return the transformed text (e.g. strip frontmatter, normalize whitespace).
  42	   */
  43	  preprocess?: (content: string, fileType: SupportedFileType) => string;
  44	  /**
  45	   * Progress callback invoked after each file is loaded.
  46	   */
  47	  onFileLoaded?: (info: FileLoadedInfo) => void;
  48	}
  49	
  50	export interface FileLoadedInfo {
  51	  /** Absolute path of the loaded file */
  52	  filePath: string;
  53	  /** Relative path from rootDir */
  54	  relPath: string;
  55	  /** Detected file type */
  56	  fileType: SupportedFileType;
  57	  /** Number of chunks produced for this file */
  58	  chunkCount: number;
  59	  /** Running count of files loaded so far */
  60	  filesLoadedSoFar: number;
  61	}
  62	
  63	export interface LoadedDocument {
  64	  /** Unique document ID */
  65	  id: string;
  66	  /** Text content (or chunk) */
  67	  content: string;
  68	  /** Metadata */
  69	  metadata: Record<string, unknown>;
  70	}
  71	
  72	export interface LoadResult {
  73	  /** All loaded documents/chunks */
  74	  documents: VectorDocumentInput[];
  75	  /** Number of files scanned */
  76	  filesScanned: number;
  77	  /** Number of files loaded (passed filters) */
  78	  filesLoaded: number;
  79	  /** Number of chunks produced */
  80	  chunksProduced: number;
  81	}
  82	
  83	// ── Extension Mapping ────────────────────────────────────────────────────────
  84	
  85	const EXTENSION_MAP: Record<string, SupportedFileType> = {
  86	  ".md": "markdown",
  87	  ".mdx": "markdown",
  88	  ".json": "json",
  89	  ".jsonl": "json",
  90	  ".ts": "typescript",
  91	  ".tsx": "typescript",
  92	  ".js": "text",
  93	  ".jsx": "text",
  94	  ".mjs": "text",
  95	  ".cjs": "text",
  96	  ".txt": "text",
  97	  ".log": "text",
  98	  ".yaml": "text",
  99	  ".yml": "text",
 100	  ".toml": "text",
 101	  ".ini": "text",
 102	  ".cfg": "text",
 103	  ".env": "text",
 104	  ".sh": "text",
 105	  ".bash": "text",
 106	  ".zsh": "text",
 107	  ".py": "text",
 108	  ".go": "text",
 109	  ".rs": "text",
 110	  ".java": "text",
 111	  ".c": "text",
 112	  ".cpp": "text",
 113	  ".h": "text",
 114	  ".css": "text",
 115	  ".html": "text",
 116	  ".xml": "text",
 117	  ".sql": "text",
 118	};
 119	
 120	const DEFAULT_EXTENSIONS = Object.keys(EXTENSION_MAP);
 121	
 122	// ── Document Loader ──────────────────────────────────────────────────────────
 123	
 124	export class DocumentLoader {
 125	  private rootDir: string;
 126	  private extensions: Set<string>;
 127	  private excludePatterns: string[];
 128	  private maxFileSize: number;
 129	  private chunkSize: number;
 130	  private chunkOverlap: number;
 131	  private idPrefix: string;
 132	  private preprocess: ((content: string, fileType: SupportedFileType) => string) | null;
 133	  private onFileLoaded: ((info: FileLoadedInfo) => void) | null;
 134	
 135	  constructor(options: DocumentLoaderOptions) {
 136	    if (!options.rootDir) throw new RAGError("LOADER_ERROR", "rootDir is required");
 137	    this.rootDir = options.rootDir;
 138	    this.extensions = new Set(options.extensions ?? DEFAULT_EXTENSIONS);
 139	    this.excludePatterns = options.exclude ?? [
 140	      "node_modules",
 141	      ".git",
 142	      "dist",
 143	      "build",
 144	      ".next",
 145	      "coverage",
 146	    ];
 147	    this.maxFileSize = options.maxFileSize ?? 1_000_000; // 1MB
 148	    this.chunkSize = options.chunkSize ?? 1500;
 149	    this.chunkOverlap = options.chunkOverlap ?? 200;
 150	    this.idPrefix = options.idPrefix ?? "";
 151	    this.preprocess = options.preprocess ?? null;
 152	    this.onFileLoaded = options.onFileLoaded ?? null;
 153	  }
 154	
 155	  // ── Synchronous API ──────────────────────────────────────────────────────
 156	
 157	  /**
 158	   * Load all matching files from the root directory (synchronous).
 159	   */
 160	  load(): LoadResult {
 161	    const files = this.scanDir(this.rootDir);
 162	    const documents: VectorDocumentInput[] = [];
 163	    let filesLoaded = 0;
 164	
 165	    for (const filePath of files) {
 166	      try {
 167	        const result = this.processFile(filePath, filesLoaded);
 168	        if (!result) continue;
 169	
 170	        filesLoaded++;
 171	        documents.push(...result.docs);
 172	      } catch {
 173	        // Skip files that can't be read
 174	      }
 175	    }
 176	
 177	    return {
 178	      documents,
 179	      filesScanned: files.length,
 180	      filesLoaded,
 181	      chunksProduced: documents.length,
 182	    };
 183	  }
 184	
 185	  /**
 186	   * Load a single file and return its document inputs (synchronous).
 187	   */
 188	  loadFile(filePath: string): VectorDocumentInput[] {
 189	    const result = this.processFile(filePath, 0);
 190	    return result?.docs ?? [];
 191	  }
 192	
 193	  // ── Asynchronous API ─────────────────────────────────────────────────────
 194	
 195	  /**
 196	   * Load all matching files from the root directory (async).
 197	   *
 198	   * Uses `node:fs/promises` so the event loop is not blocked during I/O.
 199	   */
 200	  async loadAsync(): Promise<LoadResult> {
 201	    const files = await this.scanDirAsync(this.rootDir);
 202	    const documents: VectorDocumentInput[] = [];
 203	    let filesLoaded = 0;
 204	
 205	    for (const filePath of files) {
 206	      try {
 207	        const result = await this.processFileAsync(filePath, filesLoaded);
 208	        if (!result) continue;
 209	
 210	        filesLoaded++;
 211	        documents.push(...result.docs);
 212	      } catch {
 213	        // Skip files that can't be read
 214	      }
 215	    }
 216	
 217	    return {
 218	      documents,
 219	      filesScanned: files.length,
 220	      filesLoaded,
 221	      chunksProduced: documents.length,
 222	    };
 223	  }
