 225	  /**
 226	   * Load a single file and return its document inputs (async).
 227	   */
 228	  async loadFileAsync(filePath: string): Promise<VectorDocumentInput[]> {
 229	    const result = await this.processFileAsync(filePath, 0);
 230	    return result?.docs ?? [];
 231	  }
