 276	  // ── Internal ─────────────────────────────────────────────────────────────
 277	
 278	  private processFile(
 279	    filePath: string,
 280	    loadedSoFar: number,
 281	  ): { docs: VectorDocumentInput[] } | null {
 282	    const content = this.readAndPreprocess(filePath);
 283	    if (!content) return null;
 284	
 285	    const relPath = relative(this.rootDir, filePath);
 286	    const fileType = this.getFileType(filePath);
 287	    const chunks = this.chunkText(content);
 288	    const docs = this.buildDocuments(relPath, fileType, chunks);
 289	
 290	    if (this.onFileLoaded) {
 291	      this.onFileLoaded({
 292	        filePath,
 293	        relPath,
 294	        fileType,
 295	        chunkCount: chunks.length,
 296	        filesLoadedSoFar: loadedSoFar + 1,
 297	      });
 298	    }
 299	
 300	    return { docs };
 301	  }
 302	
 303	  private async processFileAsync(
 304	    filePath: string,
 305	    loadedSoFar: number,
 306	  ): Promise<{ docs: VectorDocumentInput[] } | null> {
 307	    const content = await this.readAndPreprocessAsync(filePath);
 308	    if (!content) return null;
 309	
 310	    const relPath = relative(this.rootDir, filePath);
 311	    const fileType = this.getFileType(filePath);
 312	    const chunks = this.chunkText(content);
 313	    const docs = this.buildDocuments(relPath, fileType, chunks);
 314	
 315	    if (this.onFileLoaded) {
 316	      this.onFileLoaded({
 317	        filePath,
 318	        relPath,
 319	        fileType,
 320	        chunkCount: chunks.length,
 321	        filesLoadedSoFar: loadedSoFar + 1,
 322	      });
 323	    }
 324	
 325	    return { docs };
 326	  }
 327	
 328	  private buildDocuments(
 329	    relPath: string,
 330	    fileType: SupportedFileType,
 331	    chunks: string[],
 332	  ): VectorDocumentInput[] {
 333	    return chunks.map((chunk, i) => ({
 334	      id: this.idPrefix
 335	        ? `${this.idPrefix}:${relPath}:${i}`
 336	        : `${relPath}:${i}`,
 337	      content: chunk,
 338	      metadata: {
 339	        source: relPath,
 340	        fileType,
 341	        chunkIndex: i,
 342	        totalChunks: chunks.length,
 343	      },
 344	    }));
 345	  }
 346	
 347	  private scanDir(dir: string): string[] {
 348	    const results: string[] = [];
 349	    try {
 350	      const entries = readdirSync(dir, { withFileTypes: true });
 351	      for (const entry of entries) {
 352	        const fullPath = join(dir, entry.name);
 353	        const relPath = relative(this.rootDir, fullPath);
 354	
 355	        if (this.shouldExclude(relPath)) continue;
 356	
 357	        if (entry.isDirectory()) {
 358	          results.push(...this.scanDir(fullPath));
 359	        } else if (entry.isFile()) {
 360	          const ext = extname(entry.name).toLowerCase();
 361	          if (this.extensions.has(ext)) {
 362	            results.push(fullPath);
 363	          }
 364	        }
 365	      }
 366	    } catch {
 367	      // Skip directories that can't be read
 368	    }
 369	    return results;
 370	  }
 371	
 372	  private async scanDirAsync(dir: string): Promise<string[]> {
 373	    const results: string[] = [];
 374	    try {
 375	      const entries = await readdir(dir, { withFileTypes: true });
 376	      for (const entry of entries as Dirent[]) {
 377	        const fullPath = join(dir, entry.name);
 378	        const relPath = relative(this.rootDir, fullPath);
 379	
 380	        if (this.shouldExclude(relPath)) continue;
 381	
 382	        if (entry.isDirectory()) {
 383	          results.push(...await this.scanDirAsync(fullPath));
 384	        } else if (entry.isFile()) {
 385	          const ext = extname(entry.name).toLowerCase();
 386	          if (this.extensions.has(ext)) {
 387	            results.push(fullPath);
 388	          }
 389	        }
 390	      }
 391	    } catch {
 392	      // Skip directories that can't be read
 393	    }
 394	    return results;
 395	  }
 396	
 397	  private shouldExclude(relPath: string): boolean {
 398	    return this.excludePatterns.some((pattern) => {
 399	      if (pattern.includes("*") || pattern.includes("?")) {
 400	        // Simple glob: match against each path segment
 401	        const segments = relPath.split("/");
 402	        return segments.some((s) => this.simpleGlob(s, pattern));
 403	      }
 404	      return relPath.includes(pattern);
 405	    });
 406	  }
 407	
 408	  private simpleGlob(text: string, pattern: string): boolean {
 409	    const regex = new RegExp(
 410	      "^" + pattern.replace(/\./g, "\\.").replace(/\*/g, ".*").replace(/\?/g, ".") + "$",
 411	    );
 412	    return regex.test(text);
 413	  }
 414	
 415	  private readAndPreprocess(filePath: string): string | null {
 416	    try {
 417	      const fileStat = statSync(filePath);
 418	      if (fileStat.size > this.maxFileSize) return null;
 419	      if (fileStat.size === 0) return null;
 420	      let content = readFileSync(filePath, "utf-8");
 421	      if (this.preprocess) {
 422	        content = this.preprocess(content, this.getFileType(filePath));
 423	      }
 424	      return content;
 425	    } catch {
 426	      return null;
 427	    }
 428	  }
 429	
 430	  private async readAndPreprocessAsync(filePath: string): Promise<string | null> {
 431	    try {
 432	      const fileStat = await stat(filePath);
 433	      if (fileStat.size > this.maxFileSize) return null;
 434	      if (fileStat.size === 0) return null;
 435	      let content = await readFile(filePath, "utf-8");
 436	      if (this.preprocess) {
 437	        content = this.preprocess(content, this.getFileType(filePath));
 438	      }
 439	      return content;
 440	    } catch {
 441	      return null;
 442	    }
 443	  }
 444	
 445	  getFileType(filePath: string): SupportedFileType {
 446	    const ext = extname(filePath).toLowerCase();
 447	    return EXTENSION_MAP[ext] ?? "text";
 448	  }
 449	}
